-- INSERT preguntas FIR 2025 (convocatoria FSE 2025, Farmacia)
-- Fuente: Cuaderno_2025_F_0_C.pdf + respuestas_2025.xlsx
-- Generado: 206 preguntas validas de 210 impresas (4 anuladas excluidas: 83, 110, 116, 120)
-- Preguntas 1, 2, 3, 4, 17, 171 dependen visualmente de
-- una estructura/imagen/figura: se cargan con imagen_path apuntando al recorte
-- rescatado del PDF y explicacion_calidad='sin_imagen' (Groq no tiene vision,
-- la explicacion real queda pendiente de un futuro paso con modelo con vision).
-- tema queda NULL: se clasificara en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2025) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2025 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

