VALUES
  (2025, 1, '¿Con qué reactivo se tiene que tratar A para obtener hidroclorotiazida?:', 'Ácido fórmico.', 'Formaldehído.', 'Diclorometano.', 'Fosgeno.', NULL, 'b', '/imagenes-fir/2025/1.png', NULL, 'sin_imagen'),
  (2025, 2, '¿Cómo pueden sintetizarse las sulfonamidas antibacterianas indicadas a continuación?:', 'Mediante clorosulfonación de la anilina seguida de aminólisis.', 'Mediante nitración de la bencenosulfonamida seguida de reducción.', 'Mediante clorosulfonación de la acetanilida seguida de aminólisis y posterior hidrólisis.', 'Mediante clorosulfonación del nitrobenceno seguida de aminólisis y reducción.', NULL, 'c', '/imagenes-fir/2025/2.png', NULL, 'sin_imagen'),
  (2025, 3, '¿Qué afirmación relativa al compuesto cuya estructura se representa a continuación es cierta?:', 'Es un profármaco del cloruro de cetilpiridinio.', 'Es un análogo blando del cloruro de cetilpiridinio.', 'Es un homólogo estructural del cloruro de cetilpiridinio.', 'Es un bioisóstero del cloruro de cetilpiridinio.', NULL, 'b', '/imagenes-fir/2025/3.png', NULL, 'sin_imagen'),
  (2025, 4, '¿Qué afirmación referida al fármaco A es correcta?:', 'No puede atravesar la barrera hematoencefálica.', 'Posee actividad analgésica.', 'Es un antihistamínico H1.', 'Es un antagonista de los receptores D1 dopaminérgicos.', NULL, 'b', '/imagenes-fir/2025/4.png', NULL, 'sin_imagen'),
  (2025, 5, '¿A través de qué reacción metabólica se activa el enalaprilo?:', 'Oxidación aromática.', 'Oxidación bencílica.', 'Hidrólisis de la amida.', 'Hidrólisis del éster.', NULL, 'd', NULL, NULL, NULL),
  (2025, 6, '¿Qué tipo de fármaco es la carbidopa?:', 'Un antiinflamatorio.', 'Un agonista directo dopaminérgico.', 'Un precursor de la dopamina.', 'Un inhibidor de la biosíntesis periférica de dopamina.', NULL, 'd', NULL, NULL, NULL),
  (2025, 7, '¿Por qué los inhibidores nucleosídicos de la transcriptasa inversa, como la zidovudina, deben fosforilarse intracelularmente?:', 'Para aumentar su liposolubilidad y facilitar el paso a través de membranas celulares.', 'Para aumentar la afinidad por la ADN polimerasa viral.', 'Para convertirse en sus formas trifosfato activas que compiten con los nucleótidos naturales.', 'Para ser degradados y eliminados más rápidamente, reduciendo la toxicidad.', NULL, 'c', NULL, NULL, NULL),
  (2025, 8, '¿Cuál es el mecanismo de acción de los inhibidores de las histonas desacetilasas (HDACs) utilizados como agentes antineoplásicos?:', 'Inhiben la metilación de las histonas, promoviendo la compactación del ADN.', 'Impiden la eliminación de los grupos acetilo de las histonas, favoreciendo la transcripción génica.', 'Desfosforilan residuos de serina en histonas, reduciendo la expresión génica.', 'Inhiben la acetilación de histonas, bloqueando la replicación del ADN.', NULL, 'b', NULL, NULL, NULL),
  (2025, 9, '¿Qué función tiene la catecol-O-metiltransferasa (COMT) en el metabolismo de fármacos?:', 'Oxida un grupo metilo presente en derivados catecólicos.', 'Metila un grupo hidroxilo presente en derivados catecólicos.', 'Desamina fármacos derivados de catecolaminas.', 'Hidroxila el anillo aromático de derivados catecólicos.', NULL, 'b', NULL, NULL, NULL),
  (2025, 10, '¿Cuál es el grupo funcional clave responsable de la unión al ion Zn2+ en los inhibidores de la enzima convertidora de angiotensina (ECA) como el captopril?:', 'Grupo carboxilato.', 'Grupo tiol.', 'Grupo amida.', 'Grupo éster.', NULL, 'b', NULL, NULL, NULL),
  (2025, 11, '¿Qué evento ocurre tras la activación de un receptor acoplado a proteína G (GPCR)?:', 'La subunidad α intercambia GDP por GTP y se disocia del complejo βγ, iniciando la señalización.', 'La proteína G se fosforila directamente sin activar ninguna vía.', 'El receptor se internaliza sin activar ninguna vía.', 'Se une ATP al receptor, lo que produce la apertura de un canal iónico.', NULL, 'a', NULL, NULL, NULL),
  (2025, 12, '¿Cuál es la función principal del glutatión (GSH) en el metabolismo de xenobióticos?:', 'Oxidar compuestos lipofílicos para aumentar su solubilidad en agua.', 'Servir como cofactor redox para las monooxigenasas del citocromo P450.', 'Conjugar compuestos electrófilos mediante su grupo sulfhidrilo, favoreciendo su detoxificación y excreción como ácidos mercaptúricos.', 'Reducir intermediarios radicalarios generados durante la β-oxidación de ácidos grasos.', NULL, 'c', NULL, NULL, NULL),
  (2025, 13, '¿Cuál de las siguientes reacciones metabólicas es de Fase II?:', 'Metilación.', 'N-hidroxilación.', 'Reducción de nitrocompuestos.', 'Hidrólisis de ésteres.', NULL, 'a', NULL, NULL, NULL),
