  (2025, 15, '¿Qué fragmento estructural de la L-dopa permite que se absorba por transporte activo?:', 'El grupo catecol.', 'El anillo bencénico.', 'El fragmento de α-aminoácido tirosina.', 'El grupo feniletilamina.', NULL, 'c', NULL, NULL, NULL),
  (2025, 16, '¿A través de qué diana biológica ejerce la tetracaína su acción anestésica local?:', 'Receptores β-adrenérgicos.', 'Dihidropteroato sintasa.', 'Lípidos de membrana.', 'Canales de sodio dependientes de potencial.', NULL, 'd', NULL, NULL, NULL),
