  (2025, 20, 'El número máximo de Clostridium perfringens (y sus esporas) que se permiten en el agua de suministro para ser declarada apta para el consumo es de:', '0 UFC en 1000 mL.', '0 UFC en 100 mL.', '0 UFC en 10 mL.', '0 UFC en 1 mL.', NULL, 'b', NULL, NULL, NULL),
