  (2025, 31, 'Indique cuál de entre los siguientes microorganismos Gram negativos, se asocia mayoritariamente con las queratitis infecciosas asociadas al uso de lentes de contacto:', 'Yersinia enterocolitica.', 'Pseudomonas aeruginosa.', 'Proteus mirabilis.', 'Brucella suis.', NULL, 'b', NULL, NULL, NULL),
  (2025, 32, 'En referencia a los miembros del género Chlamydia, ¿qué característica de las referidas a continuación es INCORRECTA?:', 'Solo crecen en medios de cultivo celulares.', 'Son bacterias intracelulares estrictas.', 'Poseen diferente morfología intra y extracelular.', 'Su pared celular tiene una gruesa capa de peptidoglucano.', NULL, 'd', NULL, NULL, NULL),
