  (2025, 64, '¿Qué sistema de grupo sanguíneo es el más importante en la transfusión de sangre y en el trasplante de órganos sólidos?:', 'Sistema Rh.', 'Sistema ABO.', 'Sistema Kell.', 'Sistema MNS.', NULL, 'b', NULL, NULL, NULL),
  (2025, 65, '¿Cuál es la causa más frecuente de anemia ferropénica en el adulto en nuestro medio?:', 'Déficit de aporte de hierro en la alimentación.', 'Pérdida crónica de pequeñas cantidades de sangre.', 'Problemas con la absorción de hierro por el aparato digestivo.', 'Alteración en el transporte sanguíneo de hierro.', NULL, 'b', NULL, NULL, NULL),
  (2025, 66, '¿Qué prueba de laboratorio explora alteraciones de la vía extrínseca de la coagulación?:', 'Tiempo de tromboplastina parcial activada.', 'Tiempo de obturación.', 'Tiempo de protrombina.', 'Tiempo de reptilasa.', NULL, 'c', NULL, NULL, NULL),
  (2025, 67, '¿Cuál de las siguientes combinaciones se considera más característica del síndrome de segunda motoneurona (nervio periférico)?:', 'Fuerza disminuida, signo de Babinsky e hipotonía.', 'Fuerza conservada, pérdida de sensibilidad táctil e hiperreflexia.', 'Fuerza disminuida, hipertonía e hiperreflexia.', 'Fuerza disminuida, hipotonía e hiporreflexia.', NULL, 'd', NULL, NULL, NULL),
  (2025, 68, 'En una mujer joven estudiada por hipertensión arterial, se detecta en la ecografía un nódulo suprarrenal y una elevación del cociente aldosterona/renina plasmática. ¿Qué hallazgo analítico se esperaría encontrar?:', 'Alcalosis metabólica.', 'Hiperpotasemia.', 'Hiponatremia.', 'Anemia macrocítica con déficit de vitamina B12.', NULL, 'a', NULL, NULL, NULL),
  (2025, 69, 'Sobre los mecanismos de compensación de la insuficiencia cardíaca, seleccione la afirmación INCORRECTA:', 'La dilatación cardíaca aumenta la contractilidad, pero aumenta también el consumo de oxígeno y la tensión de la pared miocárdica.', 'El aumento en la secreción de angiotensina II disminuye la poscarga, pero causa hipotensión arterial.', 'La hipertrofia miocárdica concéntrica incrementa la contractilidad, pero disminuye la distensibilidad ventricular.', 'El aumento de la secreción de hormona antidiurética incrementa la precarga, pero favorece la formación de edemas.', NULL, 'b', NULL, NULL, NULL),
  (2025, 70, 'Un paciente acude a urgencias por una crisis hipertensiva. Presenta hipoxemia y crepitantes bilaterales en la auscultación pulmonar. ¿Qué dato se espera encontrar con mayor probabilidad en la anamnesis?:', 'Ortopnea.', 'Dolor en hipocondrio derecho.', 'Edema de los tobillos.', 'Distensión abdominal.', NULL, 'a', NULL, NULL, NULL),
