  (2025, 131, '¿Cuál de las siguientes afirmaciones es correcta con relación a los grupos glicosil fosfatidil inositol (GPI)?:', 'Modifican el extremo N terminal de la proteína aceptora.', 'La parte oligosacarídica contiene tres residuos de manosa y uno de glucosamina.', 'Están presentes en la membrana plasmática de los organismos procariotas y eucariotas.', 'El inositol puede ser modificado por pequeños péptidos catiónicos transmembranales.', NULL, 'b', NULL, NULL, NULL),
  (2025, 132, '¿Cuál de las siguientes afirmaciones es INCORRECTA en relación a la técnica de PCR (reacción en cadena de la polimerasa)?:', 'Se emplea una ADN polimerasa termorresistente.', 'Es necesario un ARN complementario a una de las dos cadenas del ADN.', 'Se requieren dos oligonucleótidos, cada uno de ellos complementario a cada una de las cadenas del ADN.', 'El ADN se debe calentar a una temperatura que produzca la disociación de sus dos cadenas.', NULL, 'b', NULL, NULL, NULL),
