  (2025, 136, '¿Cuál es el papel de los fragmentos de Okazaki en la replicación del ADN?:', 'Participan en la síntesis de la hebra conductora.', 'Participan en la síntesis de la hebra rezagada.', 'Participan en la formación de los telómeros.', 'Son las secuencias del ADN a las que se une la Dna A.', NULL, 'b', NULL, NULL, NULL),
  (2025, 137, '¿Cuál es la función de la caperuza del extremo 5’ del ARN mensajero eucariota?:', 'Es necesaria para que el ARN mensajero atraviese el poro nuclear.', 'Participa en el corte de los intrones.', 'Participa en el empalme de los exones.', 'Protege al ARN mensajero de las ribonucleasas.', NULL, 'd', NULL, NULL, NULL),
