  (2025, 148, '¿Qué parámetro se utiliza para validar la precisión de un método analítico en control de calidad farmacéutico?:', 'Límite de detección.', 'Coeficiente de variación.', 'Tiempo de retención.', 'Resolución.', NULL, 'b', NULL, NULL, NULL),
  (2025, 149, '¿Cuál es la principal ventaja del detector de masas respecto al detector ultravioleta visible en la cromatografía líquida de alta resolución (HPLC)?:', 'Mayor simplicidad operativa.', 'Menor coste de análisis.', 'Permite identificar compuestos incluso en mezclas complejas.', 'Menor necesidad de calibración.', NULL, 'c', NULL, NULL, NULL),
