  (2025, 152, '¿En qué propiedad física se basan las técnicas instrumentales de análisis de la turbidimetría y la nefelometría?:', 'En la absorción de radiación.', 'En la refracción de radiación.', 'En la dispersión de radiación.', 'En la emisión de radiación.', NULL, 'c', NULL, NULL, NULL),
