  (2025, 157, '¿Cuál de estos procedimientos es el que se lleva a cabo en el método de calibración de las adiciones estándar?:', 'Se determina la abscisa en el origen.', 'Se preparan patrones con concentraciones conocidas de analito.', 'Se representa la señal frente a la concentración de analito de los patrones.', 'Se añade a todas las muestras (blanco, patrones y problema) una cantidad fija de una sustancia.', NULL, 'a', NULL, NULL, NULL),
  (2025, 158, '¿Qué representa la letra griega “ν” en la siguiente ecuación?: 𝟏 𝟐𝝅√𝒌 𝒉 𝑬= (𝝂+ 𝟐) · 𝒎𝒓', 'La constante de fuerza del enlace.', 'La masa reducida de los átomos que constituyen el enlace.', 'El número cuántico vibracional.', 'La frecuencia vibracional del enlace.', NULL, 'c', NULL, NULL, NULL),
