  (2025, 160, '¿Cuál de estos fenómenos origina ensanchamiento de las bandas espectrales en la espectroscopía atómica?:', 'La radiación parásita.', 'Las interferencias químicas.', 'El efecto Zeeman.', 'El efecto Doppler.', NULL, 'd', NULL, NULL, NULL),
  (2025, 161, 'Si el orden de reacción con respecto a un reactivo A en un determinado proceso es dos:', 'La vida media de ese reactivo A es independiente de la concentración inicial de A.', 'La vida media de ese reactivo A es directamente proporcional a la concentración inicial de A.', 'La vida media de ese reactivo A es inversamente proporcional a la concentración inicial de A.', 'La vida media de ese reactivo A es directamente proporcional al cuadrado de la concentración inicial de A.', NULL, 'c', NULL, NULL, NULL),
  (2025, 162, 'En un fluido newtoniano, la viscosidad (η) es:', 'Constante y no depende del gradiente de velocidad.', 'Variable y depende del tiempo de flujo.', 'Proporcional al cuadrado del gradiente de velocidad.', 'Inversamente proporcional al gradiente de concentración.', NULL, 'a', NULL, NULL, NULL),
  (2025, 163, 'En un sistema donde la difusión de una sustancia es uniforme y estacionaria, ¿cuál de las siguientes afirmaciones es correcta?:', 'El flujo de difusión aumenta con el tiempo.', 'El gradiente de concentración permanece constante con el tiempo.', 'La difusión no depende del coeficiente de difusión.', 'La concentración del soluto varía de forma no lineal con la posición.', NULL, 'b', NULL, NULL, NULL),
