  (2025, 165, 'La inducción de anemia hemolítica por medicamentos relativamente inocuos en unos determinados individuos se debe:', 'A un fenómeno de resistencia al fármaco.', 'A una deficiencia de la glucosa-6-fosfato deshidrogenasa (G6PD) que incrementa el potencial reductor del hematíe, haciéndolo más frágil.', 'A una deficiencia de la G6PD que provoca una disminución del potencial reductor del hematíe, debilitando la integridad de la membrana.', 'A que provocan un incremento del glutatión en la célula sanguínea.', NULL, 'c', NULL, NULL, NULL),
  (2025, 166, 'El antituberculoso isoniazida no se puede tomar con queso curado ya que:', 'El efecto inhibidor de la monoamino oxidasa (MAO) de la isoniazida puede hacer que se incrementen los niveles plasmáticos de aminas presoras y producir hipertensión arterial.', 'El efecto inhibidor de la MAO de la isoniazida puede antagonizar los efectos antiinfecciosos frente a Mycobacterium tuberculosis.', 'Se bloquea su absorción gástrica al formar quelatos.', 'Se debe esperar una semana después de terminar el tratamiento con isoniazidanicotínicos.', NULL, 'a', NULL, NULL, NULL),
  (2025, 167, 'El flumazenilo:', 'Es un antagonista inverso del complejo macromolecular del ionóforo de cloro mediado por GABA.', 'Es un agonista parcial de las β-carbolinas.', 'Es un antagonista de benzodiacepinas.', 'Es un α-adrenérgico.', NULL, 'c', NULL, NULL, NULL),
  (2025, 168, 'El principal responsable de la toxicidad del paracetamol es:', 'El derivado glucurónico formado durante su biotransformación.', 'La N-acetil-p-quinoneimina (NAPQI), metabolito intermedio de su biotransformación.', 'La N-acetil-p-quinoneimina (NAPQI), metabolito final de su biotransformación.', 'El derivado sulfurado formado durante su biotransformación.', NULL, 'b', NULL, NULL, NULL),
  (2025, 169, '¿Cuáles de los siguientes signos clínicos condicionan el pronóstico de una intoxicación por antidepresivos tricíclicos?:', 'Trastornos neurológicos.', 'Síndrome anticolinérgico.', 'Alteraciones del electrocardiograma: QRS más ancho.', 'Alteraciones gastrointestinales.', NULL, 'c', NULL, NULL, NULL),
  (2025, 170, '¿Cuál de las siguientes afirmaciones es cierta?:', 'A y B tienen la misma solubilidad en H2O.', 'A y C tienen el mismo punto de ebullición.', 'B y C tienen diferente momento dipolar.', 'B y C tienen diferente signo de la rotación óptica específica.', NULL, 'd', NULL, NULL, NULL),
