  (2025, 172, '¿Cuál de las siguientes afirmaciones es cierta en relación al efecto de un sustituyente activante en las reacciones de sustitución electrófila aromática?:', 'Dirige en orto y para.', 'Dirige en meta.', 'Dirige en orto y para si es un sustituyente activante débil y en meta si es un activante fuerte.', 'Disminuye la reactividad del anillo.', NULL, 'a', NULL, NULL, NULL),
  (2025, 173, 'Las fuerzas intermoleculares entre las moléculas de clorometano son:', 'Fuerzas ion-dipolo.', 'Fuerzas dipolo-dipolo inducido.', 'Fuerzas dipolo-dipolo.', 'Puentes de hidrógeno.', NULL, 'c', NULL, NULL, NULL),
